var w = $("#"+id);

function statusLabel(status) {
    var colors = { completed: 'green', cancelled: 'grey', in_progress: 'blue', error: 'red' };
    var color = colors[status] || 'grey';
    return '<span class="ui tiny ' + color + ' label">' + status + '</span>';
}

function load() {
    w.find('.loader').show();
    w.find('table.runs').hide();
    w.find('.no-runs').hide();
    w.find('.runs-body').empty();

    endpoint.schema('ai').view('run_summary').rows({
        order_by: { column: 'started_at', direction: 'desc' }
    }).then(function(runs) {
        w.find('.loader').hide();
        if (runs.length === 0) {
            w.find('.no-runs').show();
            return;
        }
        w.find('table.runs').show();
        runs.forEach(function(run) {
            var commits = run.get('commits') || [];
            var commitsHtml = '';
            if (commits && commits.length > 0) {
                commitsHtml = commits.map(function(c) {
                    return '<div>' + (c.bundle || '') + ': ' + (c.message || '') + '</div>';
                }).join('');
            } else {
                commitsHtml = '-';
            }
            w.find('.runs-body').append(
                '<tr>' +
                '<td>' + statusLabel(run.get('status')) + '</td>' +
                '<td>' + (run.get('agent') || '-') + '</td>' +
                '<td style="max-width:300px">' + (run.get('intent') || '-') + '</td>' +
                '<td nowrap>' + (run.get('duration') || '-') + '</td>' +
                '<td class="commits-list">' + commitsHtml + '</td>' +
                '</tr>'
            );
        });
    }).catch(function(e) {
        w.find('.loader').hide();
        w.append('<div class="ui error message">Error: ' + e + '</div>');
        console.error('ai_run_summary error:', e);
    });
}

w.find('button.refresh').click(function() { load(); });
load();
"

