"var w = $("#"+id);

function statusLabel(status) {
    var colors = { decided: "green", open: "yellow", revisited: "grey" };
    return "<span class=\"ui tiny " + (colors[status]||"grey") + " label\">" + status + "</span>";
}

function topicColor(topic) {
    var colors = { architecture: "#4a90d9", finding: "#e67e22", convention: "#27ae60", reference: "#8e44ad", open_question: "#c0392b" };
    return colors[topic] || "#999";
}

function load() {
    w.find(".loader").show();
    w.find(".content").hide();

    var contextP  = endpoint.schema("companion").table("context").rows({ order_by: { column: "updated_at", direction: "desc" } });
    var decisionP = endpoint.schema("companion").table("decision").rows({ order_by: { column: "decided_at", direction: "desc" } });
    var noteP     = endpoint.schema("companion").table("note").rows({ order_by: { column: "topic", direction: "asc" } });

    Promise.all([contextP, decisionP, noteP]).then(function(results) {
        var contexts   = results[0];
        var decisions  = results[1];
        var notes      = results[2];

        w.find(".loader").hide();
        w.find(".content").show();

        // Context
        var cb = w.find(".context-body").empty();
        contexts.forEach(function(row) {
            cb.append(
                "<tr><td class=\"context-key\" style=\"width:12em\">" + row.get("key") + "</td>" +
                "<td class=\"context-val\">" + (row.get("value") || "") + "</td></tr>"
            );
        });

        // Decisions
        var db = w.find(".decisions-body").empty();
        if (decisions.length > 0) {
            w.find(".decisions-table").show();
            decisions.forEach(function(row) {
                db.append(
                    "<tr>" +
                    "<td><strong>" + row.get("title") + "</strong></td>" +
                    "<td class=\"decision-body\">" + (row.get("decision") || "") + "</td>" +
                    "<td class=\"rationale\">" + (row.get("rationale") || "-") + "</td>" +
                    "<td>" + statusLabel(row.get("status")) + "</td>" +
                    "</tr>"
                );
            });
        }

        // Notes — group by topic
        var nb = w.find(".notes-body").empty();
        var currentTopic = null;
        notes.forEach(function(row) {
            var topic = row.get("topic");
            if (topic !== currentTopic) {
                currentTopic = topic;
                nb.append("<div class=\"note-topic\" style=\"color:" + topicColor(topic) + "; margin-top:0.8em\">" + topic + "</div>");
            }
            nb.append(
                "<div class=\"note-card\">" +
                "<div class=\"note-title\">" + row.get("title") + "</div>" +
                "<div class=\"note-body\">" + (row.get("body") || "") + "</div>" +
                "</div>"
            );
        });

    }).catch(function(e) {
        w.find(".loader").hide();
        w.append("<div class=\"ui error message\">Error: " + e + "</div>");
        console.error("companion_session_brief error:", e);
    });
}

w.find("button.refresh").click(function() { load(); });
load();"

